import urllib.request,urllib.error,json,pathlib
urls=['/','/PING.txt','/console/','/console/login','/console/index.php','/console/assets/css/app.css','/saas/PING.txt','/saas/mobile/updates/latest.json']
result=[]
for path in urls:
 try:
  req=urllib.request.Request('https://app.ontrackegy.com'+path,headers={'User-Agent':'OnTrack-DNS-Root-Probe'})
  with urllib.request.urlopen(req,timeout=4) as res:result.append([path,res.status,res.geturl(),len(res.read(600))])
 except urllib.error.HTTPError as ex:result.append([path,ex.code,ex.geturl()])
 except Exception as ex:result.append([path,type(ex).__name__])
root=pathlib.Path('/home/appontrack/public_html/saas');print(json.dumps({'urls':result,'index_exists':(root/'index.php').exists(),'console_exists':(root/'console'/'index.php').exists(),'root_htaccess':(root/'.htaccess').exists()}))
